use crate::sync_codec as c;use serde_json::{Value,json};
pub fn run(path:&str){let v:Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();let mut count=0;
 for row in v["cases"].as_array().unwrap(){let mut s=c::CycleSettings::default();s.selected_goals_csv="new".into();s.last_period_start_date="2024-02-01".into();s.average_cycle_length=row["newLength"].as_i64().unwrap() as i32;s.period_duration=6;s.is_app_lock_enabled=true;s.lock_timeout_minutes=5;s.remind_daily_log=true;assert_eq!(c::settings_payload(&s),row["settingsPayload"].as_str().unwrap());assert!(s.is_app_lock_enabled&&s.remind_daily_log);
 let p=if row["present"].as_bool().unwrap(){let mut p=c::OnboardingProfile::default();p.approximate_period_choice="EXACT".into();p.cycle_length_option="It changes a lot".into();p.cycle_length_days=25;p.period_duration_days=4;p.selected_goals_csv="preserve".into();p.last_period_date_string="2024-01-01".into();p.is_age_verified=false;
 if s.average_cycle_length!=row["previousAverage"].as_i64().unwrap() as i32{p.cycle_length_option=format!("{} days",s.average_cycle_length)}p.cycle_length_days=s.average_cycle_length;p.period_duration_days=s.period_duration;assert!(!p.is_age_verified);Some(c::profile_payload(&p))}else{None};assert_eq!(json!(p),row["profilePayload"]);count+=1;
 }eprintln!("PASS{count} current Kotlin ordinary settings/profile pure decisions+codec outputs (profile absent/present, changed/unchanged previous average); no persistence integration");}
